package com.chatsystem.user.controller.group;import com.chatsystem.shared.service.GroupService;import javafx.fxml.FXML;import javafx.scene.control.*;
public final class InviteMembersDialogController{private final GroupService groups;private long id;@FXML private TextField memberIdField;@FXML private Label feedbackLabel;public InviteMembersDialogController(GroupService g){groups=g;}public void present(long groupId){id=groupId;}@FXML private void submit(){try{var r=groups.inviteMember(id,Long.parseLong(memberIdField.getText().strip()));if(r.isSuccess())memberIdField.getScene().getWindow().hide();else feedbackLabel.setText(r.errors().get(0).message());}catch(RuntimeException e){feedbackLabel.setText("Enter a valid member ID");}}@FXML private void cancel(){memberIdField.getScene().getWindow().hide();}}
